"""Small, filesystem based implementation of chezmoi add and forget."""
import os
import shutil
import stat


def encode_component(name, mode=0):
    prefix = ""
    if name.startswith("."):
        prefix += "dot_"
        name = name[1:]
    if mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
        prefix += "executable_"
    if mode & stat.S_IWUSR == 0:
        prefix += "readonly_"
    if mode & stat.S_IRUSR == 0:
        prefix += "private_"
    return prefix + name


def target_to_source(path, dest):
    path = os.path.abspath(os.path.expanduser(path))
    dest = os.path.abspath(os.path.expanduser(dest))
    try:
        rel = os.path.relpath(path, dest)
    except ValueError:
        return None
    if rel == ".." or rel.startswith(".." + os.sep):
        return None
    result = []
    here = dest
    for part in rel.split(os.sep):
        here = os.path.join(here, part)
        try:
            mode = os.lstat(here).st_mode
        except OSError:
            mode = 0
        result.append(encode_component(part, mode))
    return os.path.join(*result) if result else ""


def handle(command, args, source, destination, dry_run=False):
    if command not in ("add", "manage", "forget", "unmanage"):
        return False, "", "", 0
    is_add = command in ("add", "manage")
    source = os.path.abspath(os.path.expanduser(source))
    destination = os.path.abspath(os.path.expanduser(destination))
    positional = []
    opts = set()
    for a in args:
        if a.startswith("--"):
            opts.add(a.split("=", 1)[0])
        elif a.startswith("-") and len(a) > 1:
            opts.update("-" + c for c in a[1:] if c.isalpha())
        else:
            positional.append(a)
    if not positional:
        return True, "", "chezmoi: requires at least 1 arg(s), only received 0\n", 1
    out, err = [], []
    for value in positional:
        path = os.path.abspath(os.path.expanduser(value))
        relsource = target_to_source(path, destination)
        if relsource is None:
            err.append(f"chezmoi: {path}: not in destination directory ({destination})")
            continue
        sourcepath = os.path.join(source, relsource)
        if is_add:
            if not os.path.lexists(path):
                if "--new" not in opts:
                    err.append(f"chezmoi: {path}: does not exist")
                    continue
                os.makedirs(os.path.dirname(path), exist_ok=True)
                open(path, "a").close()
            if dry_run:
                out.append(relsource)
                continue
            os.makedirs(os.path.dirname(sourcepath), exist_ok=True)
            if os.path.islink(path):
                if os.path.lexists(sourcepath):
                    os.unlink(sourcepath)
                os.symlink(os.readlink(path), sourcepath)
            elif os.path.isdir(path):
                os.makedirs(sourcepath, exist_ok=True)
                if "--recursive" in opts or "-r" in opts:
                    for root, dirs, files in os.walk(path):
                        for name in files:
                            f = os.path.join(root, name)
                            rp = os.path.relpath(f, destination)
                            sp = os.path.join(source, *[encode_component(p, os.lstat(os.path.join(destination, *rp.split(os.sep)[:i+1])).st_mode) for i,p in enumerate(rp.split(os.sep))])
                            os.makedirs(os.path.dirname(sp), exist_ok=True)
                            shutil.copy2(f, sp)
            else:
                shutil.copy2(path, sourcepath)
            out.append(relsource)
        else:
            if not os.path.lexists(sourcepath):
                err.append(f"chezmoi: {path}: not managed")
                continue
            if not dry_run:
                if os.path.isdir(sourcepath) and not os.path.islink(sourcepath):
                    shutil.rmtree(sourcepath)
                else:
                    os.unlink(sourcepath)
            out.append(relsource)
    return True, "".join(x + "\n" for x in out), "".join(x + "\n" for x in err), 1 if err else 0
