"""Configuration inspection commands for the chezmoi-compatible CLI."""
import os
import sys


def run(command, config_path=None, config_format=None):
    if command == 'cat-config':
        path = config_path or os.path.join(os.path.expanduser('~'), '.config', 'chezmoi', 'chezmoi.toml')
        try:
            with open(path, 'r', encoding='utf-8') as f:
                sys.stdout.write(f.read())
        except OSError as e:
            reason = e.strerror or 'error'
            print(f'chezmoi: open {path}: {reason}', file=sys.stderr)
            return 1
        return 0
    return 2
