"""Read-only implementation of chezmoi's dump command."""
import json
import os
import stat
import sys


def source_name(path):
    parts = path.split(os.sep)
    out = []
    for part in parts:
        if part.startswith('.') and part not in ('.', '..'):
            out.append(part)
            continue
        for prefix, marker in [('private_', ''), ('readonly_', ''), ('executable_', ''), ('symlink_', '')]:
            if part.startswith(prefix):
                part = part[len(prefix):]
                break
        else:
            pass
        if part.startswith('dot_'):
            part = '.' + part[4:]
        elif part.startswith('private_dot_'):
            part = '.' + part[len('private_dot_'):]
        elif part.startswith('executable_dot_'):
            part = '.' + part[len('executable_dot_'):]
        elif part.startswith('readonly_dot_'):
            part = '.' + part[len('readonly_dot_'):]
        out.append(part)
    return os.path.join(*out) if out else ''


