def yaml_scalar(s):
    if s and all(c.isalnum() or c in '._/-' for c in s) and s.lower() not in ('true','false','null','yes','no'):
        return s
    return json.dumps(s, ensure_ascii=False)


def yaml_dump(data):
    lines=[]
    for key, item in data.items():
        lines.append(yaml_scalar(key)+':')
        for k,v in item.items():
            if isinstance(v, str):
                if v.endswith('\n') and v.count('\n') == 1 and all(c.isprintable() or c in '\n\t' for c in v):
                    lines.append('  '+k+': |')
                    lines.extend('    '+x for x in v[:-1].split('\n'))
                else:
                    lines.append('  '+k+': '+yaml_scalar(v))
            else:
                lines.append('  '+k+': '+str(v).lower() if isinstance(v,bool) else '  '+k+': '+str(v))
    return '\n'.join(lines)+'\n' if lines else '{}\n'


def handle(args, source, destination=None):
