            if p in all_entries: picked[p]=all_entries[p]
            else:
                for k,v in all_entries.items():
                    if k.startswith(p.rstrip('/')+'/'): picked[k]=v
                if p not in picked and not any(k.startswith(p.rstrip('/')+'/') for k in all_entries):
                    return '', f'chezmoi: {os.path.join(root,p)}: not managed by chezmoi\n', 1
        all_entries=picked
