    for kind in (include or set()) | exclude:
        if kind not in valid:
            flag='-i, --include' if kind in (include or set()) else '-x, --exclude'
            return '', f'chezmoi: invalid argument "{kind}" for "{flag}" flag: {kind}: unknown entry type\n', 1
    aliases={'files':'file','symlinks':'symlink','dirs':'dir','scripts':'script','encrypted':'encrypted','templates':'template'}
    if include is not None: include={aliases.get(x,x) for x in include}
    exclude={aliases.get(x,x) for x in exclude}
    if include is not None or exclude:
        all_entries={k:v for k,v in all_entries.items() if (include is None or v.get('type') in include) and v.get('type') not in exclude}
    if fmt == 'yaml':
        return yaml_dump(all_entries), '', 0
    return json.dumps(all_entries, indent=2, ensure_ascii=False)+'\n', '', 0
